  'Change sign-in e-mail': 'Změnit přihlašovací e-mail',
  'Add a sign-in e-mail': 'Přidat přihlašovací e-mail',
  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': 'Zadávej ho u „Přihlásit se heslem“ místo jména profilu. Nikdy na něj nic neposíláme; zapomenuté heslo ti i tak obnoví správce.',
  'E-mail address': 'E-mailová adresa',
  'That is already your sign-in e-mail.': 'Tohle už je tvůj přihlašovací e-mail.',
  'E-mail saved': 'E-mail uložen',
  'Remove e-mail': 'Odebrat e-mail',
  'Remove your sign-in e-mail?': 'Odebrat přihlašovací e-mail?',
  'Afterwards you sign in with your profile name only.': 'Pak se budeš přihlašovat jen jménem profilu.',
  'E-mail removed': 'E-mail odebrán',
  'Too many attempts. Try again {0}.': 'Příliš mnoho pokusů. Zkus to znovu {0}.',
  'Use at least {0} characters.': 'Použij heslo aspoň s {0} znaky.',
  'That password is too long.': 'Heslo je příliš dlouhé.',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': 'Heslo se dá příliš snadno uhodnout. Zkus delší, nebo pár náhodných slov za sebou.',
  'Another profile already signs in with this name.': 'S tímto jménem se už přihlašuje jiný profil.',
  'That invite code is not valid.': 'Tento kód pozvánky není platný.',
  'Your current password is not right.': 'Současné heslo není správné.',
  'Your passkey could not be confirmed.': 'Přístupový klíč se nepodařilo potvrdit.',
  'This password is the only way into your profile, so it cannot be removed.': 'Tohle heslo je jediná cesta do tvého profilu, takže ho nejde odebrat.',
  'That reset code is wrong or has expired. Ask your admin for a new one.': 'Kód pro obnovení je špatný nebo vypršel. Požádej správce o nový.',
  'This account has been disabled.': 'Tento účet byl deaktivován.',
  'The server is busy. Try again in a moment.': 'Server je přetížený. Zkus to za chvíli znovu.',
  '1 passkey': '1 přístupový klíč',
  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'Jednorázový kód umožní tvému telefonu nebo jinému počítači přihlásit se vlastním přístupovým klíčem.',
  'Add a passkey': 'Přidat přístupový klíč',
  'Add another device': 'Přidat další zařízení',
  'Add this device': 'Přidat toto zařízení',
  'Added {0}': 'Přidáno {0}',
  'Code from your other device': 'Kód z druhého zařízení',
  'Confirm with a passkey': 'Potvrdit přístupovým klíčem',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Potvrzeno. Teď vytvoř nový přístupový klíč; prohlížeč se zeptá, kam ho uložit.',
  'Copy link': 'Kopírovat odkaz',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Vytvoř na tomto zařízení přístupový klíč pro profil „{0}“. Odteď se s ním budeš přihlašovat tady.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Každý z nich přihlašuje do tohoto profilu ze zařízení nebo správce hesel, kde je uložený. Klepnutím na klíč ho přejmenuješ nebo odebereš.',
  'Enter the code from your other device.': 'Zadej kód z druhého zařízení.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Pro toto zařízení, bezpečnostní klíč, správce hesel nebo telefon přes QR kód, který zobrazí prohlížeč. Nejdřív potvrď, že jsi to ty.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Už se s ním do tohoto profilu nepůjde přihlásit. Zařízení, které je s ním už přihlášené, přihlášené zůstane. Pokud se ztratilo, použij „Odhlásit se všude“.',
  'It is your only way in, so it cannot be removed until there is another.': 'Je to tvoje jediná cesta dovnitř, takže ho nejde odebrat, dokud nebudeš mít další.',
  'Last used {0}': 'Naposledy použito {0}',
  'Make a new code': 'Vytvořit nový kód',
  'Name, e.g. Work laptop': 'Název, např. Pracovní notebook',
  'None yet. Add one and sign in without your password.': 'Zatím žádný. Přidej si nějaký a přihlašuj se bez hesla.',
  'Passkey added': 'Přístupový klíč přidán',
  'Passkey removed': 'Přístupový klíč odebrán',
  'Passkey {0}': 'Přístupový klíč {0}',
  'Passkeys': 'Přístupové klíče',
  'Remove passkey': 'Odebrat přístupový klíč',
  'Remove this passkey?': 'Odebrat tento přístupový klíč?',
  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Naskenuj to druhým zařízením, nebo tam otevři openGym a zadej kód na přihlašovací obrazovce. Funguje jednou a jen po dobu {0} min.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Kód je špatný, už byl použit, nebo mu vypršela platnost. Vytvoř si nový na druhém zařízení.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'V tomto prohlížeči nejde potvrdit přístupovým klíčem. Udělej to na zařízení, kde nějaký máš.',
  'First confirm that it is you.': 'Nejdřív potvrď, že jsi to ty.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Tento profil nemá žádný přístupový klíč a server nepřijímá hesla, takže tady nic nemůže potvrdit, že jsi to ty. Obrať se na správce.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Tento prohlížeč neumí vytvářet přístupové klíče, takže ho kódem přidat nejde. Otevři odkaz v prohlížeči, který to umí.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Tento prohlížeč je přihlášený k profilu „{0}“. Když ho přidáš k profilu „{1}“, profil „{0}“ se tady odhlásí.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Tento kód patří k jinému profilu, který se taky jmenuje „{0}“, ne k tomu, ke kterému je přihlášený tento prohlížeč. Když ho tam přidáš, tvůj profil se tady odhlásí.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Pokračuj, jen pokud kód pochází z tvého vlastního zařízení. Tento prohlížeč se pak přihlásí k profilu „{0}“ a co tu zapíšeš, uloží se do něj.',
  'This code has expired.': 'Platnost kódu vypršela.',
  'This device already has a passkey for this profile.': 'Toto zařízení už pro tento profil přístupový klíč má.',
  'This passkey already belongs to a profile.': 'Tento přístupový klíč už patří k nějakému profilu.',
  'This profile already has as many passkeys as it can hold.': 'Tento profil už má maximální počet přístupových klíčů.',
  'Use a code from your other device': 'Použít kód z druhého zařízení',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Dostaneš kód, se kterým si tvůj telefon nebo jiný počítač vytvoří přístupový klíč pro tento profil. Nejdřív potvrď, že jsi to ty.',
  'or with your password': 'nebo heslem',
  '{0} passkeys': { one: '{0} přístupový klíč', few: '{0} přístupové klíče', other: '{0} přístupových klíčů' },
  'Each profile keeps its own plan, workouts & body weight.': 'Každý profil má vlastní plán, tréninky a tělesnou váhu.',
