  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Smaže plán, tréninky, záznamy váhy, fotky a videa z tvého profilu na tomto serveru i ve všech přihlášených zařízeních. Nejde to vrátit zpět.',
  'Sync failed: the server refused the upload as too large. Your changes have not reached the server.': 'Synchronizace se nezdařila: server odmítl nahraná data, protože jsou příliš velká. Tvoje změny se na server nedostaly.',
  'This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.': 'V tomto zařízení došlo místo: změna se v něm neuložila. S přihlášeným účtem se ale i tak odešle na server.',
