  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Tvoje jméno, přihlašovací údaje a vše ostatní o tvém účtu zůstává tady. Data jiných lidí se nikdy neposílají.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Trenér není lékař ani fyzioterapeut. Když tě něco bolí, obrať se na odborníka.',
