  'min': 'min',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Trenér přizpůsobí objem času, který opravdu máš, včetně pauz mezi sériemi.',
  'What can you train with?': 'S čím můžeš trénovat?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Vyber všechno, k čemu máš přístup. Když nic nevybereš, Trenér použije celou knihovnu cviků.',
  'Anything to work around?': 'Na co je potřeba brát ohled?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Zranění, klouby, které zlobí, pohyby, které nezvládneš, nebo praktická omezení, třeba trénink v 6 ráno v bytě.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'např. „zlobí mě levé rameno, žádný tlak nad hlavu s velkou činkou“',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Pokud tě něco opravdu bolí, zajdi za odborníkem. Trenér naplánuje trénink opatrně, ale nic diagnostikovat neumí.',
  'Anything else?': 'Ještě něco?',
  'Exercises you love': 'Oblíbené cviky',
  'e.g. “deadlifts, anything with a kettlebell”': 'např. „mrtvé tahy, cokoli s kettlebellem“',
  'Exercises you would rather not': 'Cviky, kterým se radši vyhneš',
