  'Discard this plan?': 'Zahodit tento plán?',
  'Nothing is saved, and you can ask again anytime.': 'Nic se neuloží a kdykoli můžeš požádat znovu.',
  'Revision {0}': 'Verze {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'Nahradí tvůj současný týden. Dny, které tento plán nechá prázdné, budou volné.',
  'Could not apply those changes': 'Změny se nepodařilo použít',
  'Dismiss these suggestions?': 'Zamítnout tyto návrhy?',
