  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Plán se změnil od chvíle, kdy se na něj Trenér podíval. Návrhy, které už nesedí, jsou zašedlé. Pokud je chceš znovu vidět, požádej o nové hodnocení.',
  'Doesn’t match your plan any more, so it can’t be applied.': 'Už neodpovídá tvému plánu, takže ho nejde použít.',
