  'Pair the mobile app': 'Spárovat mobilní aplikaci',
  'Connect the openGym app on your phone to this account.': 'Propoj aplikaci openGym v telefonu s tímto účtem.',
  'On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'V aplikaci openGym zvol „Připojit k vlastnímu serveru“ a zadej tuto adresu a kód níže. Platnost kódu vyprší za 5 minut.',
  'Enter your server address and the code': 'Zadej adresu serveru a kód',
