  '{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tomto zařízení byly bez přihlášení zapsány tréninky ({0}) a vážení ({1}). Přidej je do profilu, nebo nech profil přesně tak, jak je na serveru.',
  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tomto zařízení byl bez přihlášení zapsán {0} trénink a {1} vážení. Přidej je do profilu, nebo nech profil přesně tak, jak je na serveru.',
  '{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tomto zařízení byl bez přihlášení zapsán {0} trénink a vážení ({1}). Přidej je do profilu, nebo nech profil přesně tak, jak je na serveru.',
  '{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tomto zařízení byly bez přihlášení zapsány tréninky ({0}) a {1} vážení. Přidej je do profilu, nebo nech profil přesně tak, jak je na serveru.',
