  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Zkus to znovu, nebo nejdřív vyexportuj zálohu. Když budeš přesto pokračovat, kopie těchto změn zůstane v tomto zařízení, dokud se znovu nepřipojí k tomuto serveru pod tímto účtem. Pak se změny zase přidají.',
