  'Signed in as {0}': 'Přihlášení: {0}',
  'Sync now': 'Synchronizovat teď',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Změny zůstávají tady a po opětovném spárování se sloučí s tvým účtem.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Změny zůstávají tady a po opětovném přihlášení se sloučí s tvým účtem.',
  'Changes kept for {0}': 'Změny uschované pro účet {0}',
  'Added back when this device connects as that account again.': 'Přidají se zpět, až se toto zařízení znovu připojí pod tím účtem.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Změny, které tvůj server ještě nemá, zůstanou v tomto zařízení a přidají se zpět, až se znovu připojí pod tímto účtem.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Tento telefon se přepne zpět jen na místní data a kopie tvého účtu se z něj odstraní. Nejdřív se ověří, že tvůj server má všechny změny. Pokud ne, rozhodneš, co s nimi bude.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Tvoje data se z tohoto prohlížeče odstraní, tvůj profil na serveru je zachová. Nejdřív se ověří, že server má všechny změny. Pokud ne, rozhodneš, co s nimi bude.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Odhlásí tento profil na všech zařízeních včetně tohoto. Spárované telefony se odpojí a bude potřeba je spárovat znovu. Přístupové klíče fungují dál, takže se jimi můžeš kdykoli znovu přihlásit.',
  '{0} change': '{0} změna',
  '{0} changes': { one: '{0} změna', few: '{0} změny', other: '{0} změn' },
  'Planned sessions start from': 'Výchozí bod naplánovaných tréninků',
  'The routine’s sets and reps. Your history decides the weight.': 'Série a opakování ze sestavy. Váhu určí tvoje historie.',
