  'Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.': 'Časované série běží ještě až 15 minut navíc. Klepni na Hotovo a zapíše se skutečná délka.',
  'Edit workout': 'Upravit trénink',
  'Workout updated': 'Trénink aktualizován',
  'Save workout changes?': 'Uložit změny tréninku?',
  'Save your edits to this workout, or keep the original record.': 'Ulož úpravy tohoto tréninku, nebo ponech původní záznam.',
  'Save changes': 'Uložit změny',
  'Don\'t save': 'Neukládat',
  'Keep editing': 'Pokračovat v úpravách',
  'This workout was deleted on another device. Your edits are still here.': 'Tento trénink byl smazán na jiném zařízení. Tvoje úpravy tu pořád jsou.',
  'Close editor': 'Zavřít editor',
  'Editing a saved workout. Date and duration stay unchanged.': 'Upravuješ uložený trénink. Datum a délka zůstanou beze změny.',
  'A pull for every press, so the shoulders stay balanced.': 'Na každý tlak jeden přítah, aby ramena zůstala v rovnováze.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Dvoudenní rotace na tři tréninky týdně, sestavená podle vybavení z tvého výčtu. Nejdřív vícekloubové cviky, na každý tlak jeden přítah a dny se překrývají natolik, aby nic nezůstalo dva týdny bez tréninku.',
  'Based on the training already in this demo profile.': 'Vychází z tréninků, které už jsou v tomto ukázkovém profilu.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Tělesná váha stojí už čtyři týdny, přestože cílem je nabírat. To se řeší v kuchyni, ne v posilovně. Plán to nebrzdí.',
  'Demo': 'Ukázka',
  'Demo data reset': 'Ukázková data obnovena',
  'Direct arm work, since you asked for it.': 'Samostatná práce na paže, podle tvého přání.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Každá nejlepší série tohoto cviku vyšla tři tréninky po sobě na RPE 9,5 nebo víc a váha se nehnula. Výměna cviku na čtyři týdny takovou stagnaci obvykle prolomí rychleji než dál dřít pořád tentýž.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Ukázková data uložená jen v tomto prohlížeči. Klidně experimentuj a měň, co chceš.',
  'Full body A': 'Celé tělo A',
  'Full body B': 'Celé tělo B',
  'Horizontal pressing, the other half of the session.': 'Horizontální tlaky, druhá polovina tréninku.',
  'Live demo. Everything stays in this browser.': 'Živá ukázka. Všechno zůstává v tomto prohlížeči.',
  'No training history yet, so starting conservatively.': 'Zatím žádná historie tréninků, takže začínáme opatrně.',
  'Passkey sign-in, sync across your devices, your own data.': 'Přihlášení přístupovým klíčem, synchronizace mezi zařízeními, tvoje vlastní data.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Vrátí ukázkový plán, tréninky a vážení do původního stavu.',
  'Reset': 'Obnovit',
  'Reset demo data': 'Obnovit ukázková data',
  'Reset demo data?': 'Obnovit ukázková data?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Přepracováno podle tvého přání. Vše ostatní zůstalo přesně tak, jak bylo.',
  'Same pattern, higher reps than day A.': 'Stejný pohybový vzor, víc opakování než v den A.',
  'Self-host it in a minute →': 'Rozjeď si ho na vlastním serveru za minutu →',
  'Self-host openGym': 'openGym na vlastním serveru',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Tréninky se protahují zhruba o patnáct minut. Tenhle doplňkový cvik oželí jednu sérii nejsnáz.',
  'Start the demo': 'Spustit ukázku',
  'The main lower-body driver, where most of the strength comes from.': 'Hlavní tahoun dolní poloviny těla, odtud přichází většina síly.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Stejné pohybové vzory, jiné varianty: dost překryvu pro progresi, dost rozdílů, aby to nezevšednělo.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Nejdřív dva velké pohybové vzory na nohy a tlaky, dokud máš plno sil.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Tahle ukázka běží celá v tvém prohlížeči s ukázkovými daty. Nic se nikam neodesílá. Přihlášení přístupovým klíčem a synchronizaci mezi zařízeními přináší server openGym, který si můžeš nainstalovat u sebe.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Tři věci stojí za změnu a jedna za pozornost. Všechno ostatní funguje: dřep i přítahy se posouvají podle plánu.',
  'Vertical pressing.': 'Vertikální tlaky.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Tenhle trénink se už tři týdny po sobě přesouvá na sobotu. Lepší, když to bude rovnou v plánu, než ho pořád ručně přesouvat.',
