  'Server address unknown': 'Adresa serveru není známá',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Spáruj zařízení znovu, nebo nejdřív vyexportuj zálohu. Pokud přesto budeš pokračovat, kopie těchto změn zůstane v tomto zařízení, dokud se znovu nepřipojí k tomuto serveru pod tímto účtem. Pak se změny zase přidají.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Přihlas se znovu, nebo nejdřív vyexportuj zálohu. Pokud přesto budeš pokračovat, kopie těchto změn zůstane v tomto zařízení, dokud se znovu nepřipojí k tomuto serveru pod tímto účtem. Pak se změny zase přidají.',
