  'Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Server je dostupný, ale požadavek aplikace odmítl (CORS). Pokud hlavičky CORS přidává reverzní proxy, třeba Traefik, nech požadavky z {0} projít do openGym beze změny. Viz „Phone app and CORS“ v docs/SELF_HOSTING.md.',
