  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym už nemůže zapisovat do složky „{0}“, takže se kopie znovu ukládají do Documents/openGym. Pro návrat vyber složku znovu.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym už nemůže zapisovat do vybrané složky, takže se kopie znovu ukládají do Documents/openGym. Pro návrat vyber složku znovu.',
