  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Jedno popíchnutí večer mezi 20:00 a 21:30 v naplánovaný den, kdy nemáš nic zapsáno. Po 3 vynechaných dnech v řadě se odmlčí až do dalšího tréninku.',
  'Everything okay?': 'Všechno v pořádku?',
