  'Scroll to 0:00 to turn the rest timer off.': 'Posuň na 0:00 a časovač pauzy se vypne.',
  'The short break between the bursts of a rest-pause set.': 'Krátká pauza mezi minisériemi v sérii rest-pause.',
  'Each exercise can have its own rest too. Set it in the exercise settings of a routine.': 'Každý cvik může mít i vlastní pauzu. Najdeš ji v nastavení cviku v sestavě.',
  'iPhone doesn’t let openGym vibrate. A sound or a flash does the job.': 'iPhone aplikaci openGym nedovolí vibrovat. Poslouží zvuk nebo bliknutí.',
  'No account, no cloud. Back it up anytime in Data & backup.': 'Bez účtu, bez cloudu. Zálohu si můžeš kdykoli udělat v sekci „Data a zálohy“.',
  'Effort per set is off. Turn it on in Settings → Workout to keep rating.': 'Náročnost série je vypnutá. Pokud chceš dál hodnotit, zapni ji v Nastavení → Trénink.',
  'Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.': 'Zadej kód, který ti druhé zařízení ukáže v Nastavení → Účet → Přidat další zařízení. Toto zařízení pak dostane vlastní přístupový klíč.',
  'Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.': 'Na webu openGym, kde už máš aktivní přihlášení, otevři Nastavení → Účet → „Spárovat mobilní aplikaci“ a pak sem zadej adresu webu a kód, který se tam zobrazí.',
  'Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': 'V prohlížeči otevři na svém webu openGym Nastavení → Účet → „Spárovat mobilní aplikaci“ a zadej nový kód, který se tam zobrazí. Co má tento telefon uložené, se sloučí s tvým účtem.',
