  'Stop writing to Apple Health?': 'Přestat zapisovat do Apple Health?',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': "Záznamy z openGym, které už v Apple Health jsou, tam můžou zůstat jako tvoje data, nebo je můžeš smazat.",
  'Your workouts in Apple Health': 'Tvoje tréninky v Apple Health',
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': "openGym může ukládat každý trénink a vážení do Apple Health a tvoje Apple Watch ti při cvičení ukážou tep.",
