  'Heart rate per set on your Apple Watch': 'Tep u každé série na Apple Watch',
  'AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.': "Máš v uších AirPods Pro 3 nebo Powerbeats Pro 2? Tvůj iPhone změří tep u každé série, pokud ho už neměří Apple Watch.",
