  'Your bar for this type, set in Your bars.': "Tvoje osa pro tento typ, nastavená v sekci Tvoje osy.",
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': "Kolik váží osy ve tvé posilovně. Každý cvik s danou osou od ní počítá kotouče, pokud nemá nastavenou vlastní. Zapsané váhy zůstávají celkové.",
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': "Většina cviků v knihovně používá „{0}“, několik „{1}“. Pokud chceš kratší osu u všech, nastav obě.",
  'Back to the standard bars': "Zpět ke standardním osám",
  'Standard bars. Tap if yours are lighter.': 'Standardní osy. Klepni, pokud jsou tvoje lehčí.',
