  'Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.': "Zaokrouhleno na celé série. Série se hlavnímu svalu počítá celá a pomocným svalům jen zčásti, takže součet za svaly je vyšší než počet tvých pracovních sérií.",
