  'Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.': 'Tvůj trénink na papíře: součty, grafy, nové rekordy a každá série. Zarámuj si ho, vytiskni nebo pošli svému trenérovi.',
