  'For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.': "Pro posilovny, kde se mísí kg a lb. Tento cvik se všude zobrazuje a zadává v této jednotce, včetně kotoučů a kroků. Součty ve Statistikách zůstávají v {0}.",
