  'Finish saves the session and moves your weights along. This practice one just quietly disappears.': "Tlačítko Dokončit uloží trénink a posune tvoje váhy dál. Tenhle cvičný prostě potichu zmizí.",
  'Finish the tour?': 'Dokončit prohlídku?',
  'Finish your workout first, then the tour is all yours.': "Nejdřív dokonči trénink, pak se můžeš pustit do prohlídky.",
