  'Let’s go': 'Jdeme na to',
  'Make it yours': "Udělej si to po svém",
  'Muscles at a glance': 'Svaly na první pohled',
  'Narrow the list by body part, type or the equipment you have.': "Zúž seznam podle partie těla, typu nebo vybavení, které máš.",
  'No thanks': 'Ne, díky',
  'Pick an exercise to see its best sets, estimated max and where it’s heading.': "Vyber cvik a uvidíš jeho nejlepší série, odhadované maximum a kam směřuje.",
  'Pointing at: {0}': "Ukazuje na: {0}",
  'Practice run': "Cvičný trénink",
  'Programmes and sharing': 'Programy a sdílení',
  'Programmes, starter plans and sharing a plan with a friend live behind this button.': "Programy, startovní plány a sdílení plánu s kamarádem najdeš pod tímto tlačítkem.",
  'Records': 'Rekordy',
  'Schedule says when, Routines says what. Build your own or grab a starter plan.': "Rozvrh říká kdy, Sestavy říkají co. Sestav si vlastní, nebo sáhni po startovním plánu.",
  'Search thousands of exercises in your language. Star your favourites and they float to the top.': "Prohledej tisíce cviků ve svém jazyce. Oblíbené označ hvězdičkou a vyplavou nahoru.",
  'See which muscles got the work and which still need rest. Tap one for details.': "Podívej se, které svaly dostaly zabrat a které ještě potřebují odpočinek. Klepnutím na sval zobrazíš podrobnosti.",
  'Show me': "Ukázat",
  'Show the tour again': "Zobrazit prohlídku znovu",
  'Skip tour': 'Přeskočit prohlídku',
  'Swipe a set': "Přejeď sérii prstem",
  'Swipe a set sideways to copy or remove it. Its number opens even more.': "Přejeď sérii prstem do strany a zkopíruješ ji nebo odebereš. Klepnutím na její číslo najdeš ještě víc.",
  'The big Start button': 'Velké tlačítko Začít',
  'The little body shows what each day works, so leg day can’t hide.': "Malá postava ukazuje, co který den procvičuje, takže se den nohou neschová.",
  'The rest timer starts by itself. Add time, or skip it if you feel heroic.': "Časovač pauzy se spustí sám. Přidej si čas, nebo pauzu přeskoč, jestli se cítíš jako hrdina.",
  'The ⋯ menu': 'Nabídka ⋯',
  'Theme, accent colour and what Home shows.': "Motiv, barva zvýraznění a co se zobrazuje na obrazovce Domů.",
  'This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.': "Tenhle je jen naoko, nic se neuloží. Každý řádek je jedna série: váha, pak opakování. Klepnutím na číslo ho změníš.",
  'Tick it off': "Odškrtni sérii",
  'Today at a glance': 'Dnešek na první pohled',
  'Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.': "Tady najdeš dnešní trénink. Jedno klepnutí a už zvedáš. Když máš volný den, dozvíš se to tady, bez výčitek.",
  'Train on fixed weekdays, or run your routines in a loop where the next one waits for you.': "Trénuj v pevné dny v týdnu, nebo nech sestavy běžet v rotaci, kde na tebe ta další počká.",
  'Want a 1-minute tour?': 'Chceš minutovou prohlídku?',
  'Week or rotation': "Týden, nebo rotace",
  'We’ll point at the good bits on the real screens. Bail out anytime.': "Ukážeme ti to nejlepší přímo na skutečných obrazovkách. Skončit můžeš kdykoli.",
  'Workout settings, layouts, notes and extra exercises hide in here.': "Nastavení tréninku, rozložení, poznámky a další cviky se schovávají tady.",
  'Workouts, streaks and everything you’ve lifted. It fills up as you train.': "Tréninky, týdny v řadě a všechna zvednutá kila. Plní se, jak trénuješ.",
  'You stopped halfway. Want to see the rest?': "Prohlídka skončila v půlce. Chceš vidět zbytek?",
  'Your data, your backups': 'Tvoje data, tvoje zálohy',
  'Your progress': 'Tvůj pokrok',
  'Your routines': 'Tvoje sestavy',
  'You’re set': "Všechno připraveno",
  'Previous year': 'Předchozí rok',
