  'Pick a day': 'Vyber den',
  'With pictures': 'S obrázky',
  'A small picture next to each exercise, like a plan from the gym.': 'Malý obrázek u každého cviku, jako plán z posilovny.',
  'This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.': "Tohle funguje v mobilní aplikaci openGym: Apple Health na iPhonu, Health Connect na Androidu.",
  'Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.': "Webhooky odesílá tvůj vlastní server openGym, takže bez něj to nejde. Připoj k němu toto zařízení v sekci Účet.",
  'Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.': "Webhooky jsou na tomto serveru vypnuté. Přidej do jeho souboru .env řádek INTEGRATIONS=webhook a server restartuj.",
  'The MCP server runs next to your own openGym server and reads your data there.': "MCP server běží vedle tvého vlastního serveru openGym a čte tvoje data přímo tam.",
  'Only what you switch on talks to anything. The rest stays out of your way.': "Připojuje se jen to, co si zapneš. Zbytek ti nebude překážet.",
  'Could not reach your server': "K tvému serveru se nepodařilo připojit",
  'Tap to try again': 'Klepni a zkus to znovu',
  'Disconnect {0}?': 'Odpojit {0}?',
  'openGym stops writing and reading. What it already wrote can stay there as your data, or go.': "openGym přestane zapisovat i číst. Co už zapsal, může tam zůstat jako tvoje data, nebo to můžeš smazat.",
  'Works with': 'Funguje s',
  'No extra connection needed: they write to {0}, and openGym reads from there.': "Žádné další připojení není potřeba: zapisují do {0} a openGym data čte odtamtud.",
  'No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.': "Žádné další připojení není potřeba: zapisují do Apple Health nebo Health Connect a mobilní aplikace openGym data čte odtamtud.",
  '{0} has no direct line to openGym, and it does not need one.': '{0} nemá s openGym přímé spojení a ani ho nepotřebuje.',
  'How it gets here': 'Jak se to sem dostane',
  '{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.': "{0} ukládá data do Apple Health v iPhonu nebo do Health Connect v Androidu. openGym si je odtamtud načítá.",
  'What openGym reads': 'Co openGym čte',
