  'Add it to the loop': "Přidej ji do rotace",
  'An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.': "Historie, rekordy a pokrok cviku se počítají z tvých tréninků. Oprav trénink a srovnají se samy.",
  'Back home, practice over. Stats is where the gains pile up. Tap it.': "Zpátky na obrazovce Domů, cvičný trénink skončil. Ve Statistikách se hromadí tvoje výsledky. Klepni na ně.",
