  'Body part': "Partie těla",
  'Build your first plan': "Sestav si první plán",
  'Call it what you call it. Other names you add help the search find it.': "Pojmenuj ho, jak mu říkáš ty. Další názvy pomůžou, aby ho vyhledávání našlo.",
  'Change them any time in Plan. Past workouts keep what you actually did.': "Měnit je můžeš kdykoli v Plánu. Minulé tréninky zůstanou tak, jak skutečně proběhly.",
