  'Everything you can tweak hides behind this little gear. Tap it.': "Všechno, co se dá doladit, se skrývá za tímhle malým ozubeným kolečkem. Klepni na něj.",
  'Export & import': 'Export a import',
  'Felt strong. Probably the coffee.': "Cítil jsem se silný. Asi tím kafem.",
  'Fine-tune it': "Dolaď ji",
  'Fix a weigh-in': "Oprava vážení",
  'Forgot one?': "Chybí ti jeden?",
  'Hands-free backups': "Automatické zálohy",
  'Head back to Home first. Tap it.': "Nejdřív se vrať na obrazovku Domů. Klepni na „Domů“.",
  'Health apps': 'Zdravotní aplikace',
  'Here’s the pretend one. Tap it.': "Tady je cvičný trénink. Klepni na něj.",
  'Home shows it on its day and Start opens it. Change it any time right here.': "Obrazovka Domů ukáže sestavu v její den a „Začít“ ji spustí. Měnit ji můžeš kdykoli přímo tady.",
  'It starts today’s plan, or lets you pick something else. Tap it for a practice run.': "Spustí dnešní plán, nebo tě nechá vybrat něco jiného. Klepni na něj a zkus si to nanečisto.",
  'Its own page': "Samostatná stránka",
  'It’s the first row of the list. Tap it.': 'Je to první řádek seznamu. Klepni na něj.',
  'Log a past workout with its own date and time. It counts like any other.': 'Zapiš minulý trénink s vlastním datem a časem. Počítá se jako každý jiný.',
  'Measurements and photos': "Měření a fotky",
  'Missing one? Make it. It works like any other: routines, workouts, records, the body map, backups and sync. Nothing is created until you tap Create.': "Nějaký chybí? Vytvoř si ho. Funguje jako každý jiný: sestavy, tréninky, rekordy, mapa svalů, zálohy i synchronizace. Nic se nevytvoří, dokud neklepneš na „Vytvořit cvik“.",
  'Moving in?': "Přecházíš odjinud?",
