  'Name it': "Pojmenuj to",
  'Name, muscles, equipment and a photo': 'Název, svaly, vybavení a fotka',
  'New routines start on the Routines side. Tap Routines.': "Nové sestavy se zakládají v části Sestavy. Klepni na „Sestavy“.",
