  'Streak badges': "Odznaky za týdny v řadě",
  'Streak freezes': "Zmrazení řady",
  'Streak freezes: {0} of {1}': "Zmrazení řady: {0} z {1}",
  'Week done. The flame lives on.': "Týden splněn. Plamen hoří dál.",
