  'One more week with a workout earns a freeze.': 'Ještě jeden týden s tréninkem a získáš zmrazení.',
  '{0} more weeks with a workout earn a freeze.': { one: 'Ještě {0} týden s tréninkem a získáš zmrazení.', few: 'Ještě {0} týdny s tréninkem a získáš zmrazení.', many: 'Ještě {0} týdne s tréninkem a získáš zmrazení.', other: 'Ještě {0} týdnů s tréninkem a získáš zmrazení.' },
  'Watch on YouTube': "Přehrát na YouTube",
  'Opens a search for good form': "Vyhledá videa se správnou technikou",
  'Share with a friend': 'Sdílet s kamarádem',
  'As a routine they can do too': 'Jako sestavu, kterou si může zacvičit taky',
  'Nothing to share in this one.': "V tomhle tréninku není co sdílet.",
  'Link copied. Paste it to a friend.': "Odkaz zkopírován. Pošli ho kamarádovi.",
  'That one’s too big for a link, so it goes as a plan file.': "Tahle sestava je na odkaz moc velká, takže se pošle jako soubor plánu.",
  'Here’s my {0} on openGym 💪': "Moje sestava „{0}“ v openGym 💪",
  'Couldn’t make a link for this one.': "Odkaz pro tuto sestavu se nepodařilo vytvořit.",
  'A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.': "Odkaz na „{0}“. Kamarád na něj klepne a přidá si sestavu do svého openGym. Sestava je uložená přímo v odkazu, bez serveru jako prostředníka.",
  'Include my weights': "Poslat i moje váhy",
  'Off: just sets, reps and rest. They pick their own weights.': "Vypnuto: jen série, opakování a pauzy. Váhy si zvolí sami.",
  'So they know who it’s from.': "Ať ví, od koho to je.",
  'Share link': 'Sdílet odkaz',
  'From {0}': "Od uživatele {0}",
  'Added as a new routine. Nothing you already have is touched.': "Přidá se jako nová sestava. Nic z toho, co už máš, se nezmění.",
  'Add to my routines': 'Přidat do mých sestav',
  'Added to your routines': 'Přidáno do tvých sestav',
  'This link is from a newer openGym. Update the app to open it.': "Odkaz je z novější verze openGym. Otevřeš ho po aktualizaci aplikace.",
  'This browser can’t open this link. Try it in the openGym app.': "Tento prohlížeč odkaz neotevře. Zkus to v aplikaci openGym.",
  'Nothing in this routine works here, sorry.': "Promiň, nic z této sestavy tu nefunguje.",
  'This routine link is broken or cut off.': "Odkaz na sestavu je poškozený nebo useknutý.",
  '(from {0})': "(od uživatele {0})",
  'Mostly in the morning. The early bird gets the barbell.': "Většinou ráno. Ranní ptáče k čince dál doskáče.",
  'Mostly around lunch. Who needs a lunch break anyway?': "Většinou kolem oběda. Kdo potřebuje polední pauzu?",
  'Mostly in the afternoon. The sweet spot.': "Většinou odpoledne. Ideální čas.",
  'Mostly in the evening. Work, then work out.': "Většinou večer. Nejdřív práce, pak trénink.",
  'Mostly late at night. The gym is all yours.': 'Většinou pozdě v noci. Posilovna je celá tvoje.',
  'Early bird': 'Ranní ptáče',
  'Most of your sessions started before 9. The sun was still catching up.': "Většina tvých tréninků začala před devátou. Slunce teprve vstávalo.",
  'Night owl': 'Noční sova',
  'Most of your sessions started after 8 pm. The quiet gym is your gym.': "Většina tvých tréninků začala po 20:00. Tichá posilovna je tvoje posilovna.",
  'Leg-day loyalist': "Věrnost dni nohou",
  'You never skipped leg day. Stairs fear you.': "Ani jeden vynechaný den nohou. Schody se tě bojí.",
  'Clockwork': 'Jako hodinky',
  'Week after week after week. Your calendar knows your name.': "Týden co týden co týden. Tvůj kalendář tě zná jménem.",
  'Record breaker': "Rekord za rekordem",
  'So many new bests, your trophy shelf needs a trophy shelf.': 'Tolik nových rekordů, že tvoje polička na trofeje potřebuje vlastní poličku na trofeje.',
  'Weekend warrior': 'Víkendový válečník',
  'Saturdays and Sundays are for lifting. Brunch can wait.': "Soboty a neděle patří činkám. Brunch počká.",
  'Cardio comet': 'Kardio kometa',
  'Your heart is in great shape. Literally.': 'Tvoje srdce je ve skvělé formě. Doslova.',
  'In it for the long haul': 'Na dlouhou trať',
  'Long sessions, no rush. The gym is basically your second home.': "Dlouhé tréninky, žádný spěch. Posilovna je prakticky tvůj druhý domov.",
