  'Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.': "Sestavy, cviky, série a opakování, rozcvičovací série, programy, tvůj týdenní rozvrh, nastavení progrese a co se dá v tvé posilovně naložit.",
