  'Saved in the routine, scaled to your work weight': "Uloží se do sestavy a přepočítají podle pracovní váhy",
  'Saved under Plan → Programmes. It starts when you start it.': "Uloženo v Plánu → Programy. Začne, až ho spustíš.",
  'Short on time': 'Málo času',
  'Skip the rest of {0}': "Přeskočit zbytek cviku {0}",
  'Something else': 'Něco jiného',
  'Squats, presses, rows and friends get a ramp. Curls and raises start cold.': "Dřepy, tlaky, přítahy a spol. dostanou postupný náběh. Bicepsové zdvihy a upažování jdou rovnou bez rozcvičky.",
  'Straight into the work sets.': 'Rovnou do pracovních sérií.',
  'That workout is over, so these can’t be applied any more.': "Tento trénink už skončil, návrhy proto nejde použít.",
  'The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.': "Aplikace odvodí rozcvičku od tvé pracovní váhy: u těžké přidá víc rozcvičovacích sérií, u lehké méně, a počítá s kotouči tvé posilovny.",
  'The rack is taken, so do it at the end. The rest of the session does not need it.': "Stojan je obsazený, tak to dej na konec. Zbytek tréninku ho nepotřebuje.",
  'There’s no workout running.': "Neprobíhá žádný trénink.",
  'These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.': "Tyto rozcvičovací série jsou v každém tréninku před pracovními sériemi. Počítají se jako podíl pracovní váhy, takže rostou s ní.",
  'This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.': "Tohle je demo, takže za mnou žádný AI model není. Na tvém vlastním serveru čtu tvůj trénink a navrhuju takovéhle změny.",
  'Warm-up {0}': "Rozcvičovací série {0}",
  'Warm-ups': "Rozcvičovací série",
  'What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.': "Co se děje? Trenér navrhne pár změn pro zbytek tohoto tréninku. Zapsané série zůstanou beze změny.",
  'Where, and what movement hurts? (optional)': "Kde a při jakém pohybu to bolí? (nepovinné)",
  'With {0} {1} today: {2}': "Dnes při {0} {1}: {2}",
  'You can keep training, the answer waits here and in the Coach.': "Můžeš dál trénovat, odpověď na tebe počká tady i u Trenéra.",
  'You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.': "Máš sílu, takže na zbytek přidám na osu trochu víc. Žádné nové maximum, jen malé popíchnutí.",
  'Your rows, as a share of the work weight, so they grow with it.': "Tvoje řádky jako podíl pracovní váhy, takže rostou spolu s ní.",
