  "{0} sees only what is on here.": "{0} vidí jen to, co je tu zapnuté.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Dovoluješ tomuto trenérovi vidět kategorie označené tady a měnit ty označené jako navrhovat nebo použít. Pokud trenér pracuje pro posilovnu, její vedoucí vidí kategorie ve svém řádku, nikdy víc než zobrazení. Můžeš to kdykoli změnit nebo se odpojit a přestane to platit ve chvíli, kdy to uděláš. Každý pohled i každá změna se zapíše do tvého záznamu sdílení, který může číst jen ty.",
