  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "Tenhle soubor tu nejde sdílet nikdy. Obrázky a animace z vestavěné knihovny jsou licencované.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "Soubor pořád nese skryté údaje, třeba polohu. Přidej ho v aplikaci znovu a nasdílej novou kopii.",
  "That is not shared any more.": "Tohle se už nesdílí.",
