  "That one is yours.": "Tohle je tvoje.",
  "That sound did not come through.": "Ten zvuk nedorazil.",
  "That tip did not come through.": "Ten tip nedorazil.",
  "The sharing text changed. Have a quick read and try again.": "Text ke sdílení se změnil. Rychle si ho přečti a zkus to znovu.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Tohle je veřejné pro všechny na tomhle serveru: každý, kdo tu má účet, to může vidět, vyzkoušet a zkopírovat. Tvoje jméno a datum jdou vždy s tím. Sdílej jen to, co je tvoje: něco, co jsi udělal, nahrál nebo máš právo předat dál. Obrázky a animace cviků z vestavěné knihovny jsou licencované a nikdy se nesmí sdílet. Sdílení můžeš kdykoli ukončit; kopie, které si už ostatní vzali, jim zůstanou.",
  "This kind of item cannot be taken.": "Tenhle druh položky si vzít nejde.",
