  "Download": "Stáhnout",
  "Changed your mind? Settings has it, any time.": "Rozmyslel sis to? V Nastaven\u00ed, kdykoli.",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "Tenhle e-mail už tu používá jiný profil. Přihlas se do něj jinak a pak propoj {0} v Nastavení.",
  "Admin? Use your passkey": "Admin? Použij přístupový klíč",
