  "Confirmed. Go ahead.": "Potvrzeno. Pokračuj.",
  "Link": "Propojit",
  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "Propoj svůj účet {0} a přihlašuj se jím od teď. Tvoje přístupové klíče fungují dál. Nejdřív rychlá kontrola, že jsi to opravdu ty.",
  "Linked. You can sign in with {0} from now on.": "Propojeno. Od teď se můžeš přihlásit přes {0}.",
