  "Not linked yet.": "Zatím nepropojeno.",
  "Off to {0}…": "Jdeme na {0}…",
  "Sign in with your provider again first, then try once more.": "Nejdřív se znovu přihlas u svého poskytovatele, pak to zkus ještě jednou.",
  "Sign in with {0}": "Přihlásit se přes {0}",
  "Sign-in cancelled. No harm done.": "Přihlášení zrušeno. Nic se nestalo.",
  "That sign-in took too long or came from another tab. Give it another go.": "To přihlášení trvalo moc dlouho nebo přišlo z jiné karty. Zkus to znovu.",
  "That was a different {0} account than the one linked to this profile.": "Tohle byl jiný účet {0} než ten, který je propojený s tímto profilem.",
  "That {0} account is already linked to another profile here.": "Tenhle účet {0} už je tu propojený s jiným profilem.",
  "This profile is already linked to a {0} account.": "Tento profil už je propojený s účtem {0}.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "Tento profil je propojený s tvým účtem {0}: kdo je přihlášený tam, je přihlášený i tady.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Tento server je jen na pozvánku a samotný {0} nestačí. Zeptej se toho, kdo ho spravuje.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "Na tomto serveru se všichni přihlašují přes {0}. Jsi tu nový? Přihlášením si vytvoříš profil.",
  "This server signs people in with {0}.": "Tento server přihlašuje lidi přes {0}.",
  "Too many attempts. Try again in a minute.": "Příliš mnoho pokusů. Zkus to za minutu.",
  "Unlink": "Odpojit",
  "Unlinked. {0} no longer signs you in here.": "Odpojeno. {0} tě tu už nepřihlásí.",
  "or use a pairing code": "nebo použij párovací kód",
  "{0} could not be reached. Try again in a moment.": "{0} není dostupný. Zkus to za chvíli znovu.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} je jediná cesta do tohoto profilu, proto zůstává propojený. Nejdřív přidej přístupový klíč.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} tě pustil dál, ale tento server bere jen určité skupiny. Požádej toho, kdo ho spravuje, ať tě přidá.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} poslal zpátky něco, co jsme nedokázali ověřit, takže se nikdo nepřihlásil. Pokud se to opakuje, stránka správy ukáže proč.",
  "Backups: {0}": "Náhradní cviky: {0}",
  "Suggested": "Návrhy",
  "Add “{0}” as a backup": "Přidat „{0}“ jako náhradu",
  "Ask the Coach for a swap": "Zeptat se trenéra na náhradu",
  "Per gym": "Podle posilovny",
  "Separate numbers per gym": "Čísla zvlášť pro každou posilovnu",
  "Last time and the next weight come from this gym only.": "Minule a další váha se berou jen z této posilovny.",
  "Brand at {0}": "Značka v {0}",
  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (nepovinné)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Stejná značka v jiné posilovně? Sdílí tato čísla. Rekordy a statistiky dál počítají všechny posilovny.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "Pro stroje a kladky, které jsou v každé posilovně jiné. Volné váhy to potřebují zřídka.",
  "All gyms": "Všechny posilovny",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "Plánované série pro {0} nesedí, takže platí ty z rutiny: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Dnešní série jsou od {0}. Tvoje rutina zůstává, jak je.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Dnešní série byly naplánované na tento den. Tvoje rutina zůstává, jak je.",
  "Body composition from your scale": "Složení těla z tvé váhy",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Tělesný tuk a čistá svalová hmota, jak je uložila tvoje váha. Najdeš je v Tělesných mírách, nikdy se nemíchají s tím, co zapisuješ.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Tělesný tuk, čistá svalová hmota, kostní hmota, tělesná voda a bazální metabolismus, jak je uložila tvoje váha. Najdeš je v Tělesných mírách, nikdy se nemíchají s tím, co zapisuješ.",
