  "No date found. Which day was it?": "Datum se nenašlo. Který to byl den?",
  "No live camera here (a browser only offers one on HTTPS). The camera app still works.": "Tady není živá kamera (prohlížeč ji nabízí jen přes HTTPS). Aplikace fotoaparátu ale funguje.",
  "No overlay": "Bez překryvu",
  "No progress photos yet. Take one now, or add one for any day before.": "Zatím žádné fotky pokroku. Vyfoť jednu teď, nebo přidej jednu k dřívějšímu dni.",
