  "Still loading the photos. Try again in a second.": "Fotky se ještě načítají. Zkus to za vteřinu.",
  "Switch camera": "Přepnout kameru",
  "The camera is switched off for openGym. Allow it in your settings, or use the camera app instead.": "Kamera je pro openGym vypnutá. Povol ji v nastavení, nebo použij aplikaci fotoaparátu.",
  "The photo you just took": "Fotka, kterou jsi právě pořídil",
  "This device could not draw the picture.": "Toto zařízení nedokázalo obrázek nakreslit.",
  "Today's photo is in. Looking good.": "Dnešní fotka je hotová. Vypadá to dobře.",
  "Use photo": "Použít fotku",
  "Use the camera app": "Použít aplikaci fotoaparátu",
