  "Needs your body fat": "Potřebuje tvůj tělesný tuk",
  "% of your 1RM": "% tvého 1RM",
  "12+ reps": "12+ opak.",
  "1RM ({0})": "1RM ({0})",
  "1RM table, RPE load, DOTS, BMI, body fat, pace.": "Tabulka 1RM, zátěž podle RPE, DOTS, BMI, tělesný tuk, tempo.",
  "A trophy and a buzz the moment a set beats a record, and the same mark in History.": "Pohár a zavibrování, jakmile série překoná rekord, a stejná značka v historii.",
  "About": "Zhruba",
  "Add your height once and every body number below fills in. It stays on this profile.": "Zadej jednou svou výšku a všechny tělesné hodnoty níže se doplní. Zůstane v tomto profilu.",
  "Beats your best e1RM": "Překonává tvé nejlepší e1RM",
  "Best": "Nejlepší",
  "Best e1RM": "Nejlepší e1RM",
  "Biggest set": "Největší série",
  "Body fat for FFMI (%)": "Tělesný tuk pro FFMI (%)",
  "Body weight ({0})": "Tělesná hmotnost ({0})",
  "Calculators, already filled in from your log.": "Kalkulačky, už vyplněné z tvého deníku.",
  "Cheer on a record": "Oslavit rekord",
  "Estimates, not a lab. Good for planning, not for arguing.": "Odhady, ne laboratoř. Dobré na plánování, ne na hádky.",
  "Heavier than ever. No pressure.": "Těžší než kdy dřív. Žádný tlak.",
  "Heaviest yet": "Nejtěžší zatím",
