  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Tato verze openGym nemá propojení s Garminem, protože část od Garminu není open source. Verze z App Store, Google Play a GitHubu ho mají.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Na tomhle telefonu není Garmin Connect. Nainstaluj ho, spáruj v něm hodinky a vrať se sem.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect potřebuje aktualizaci, než s tvými hodinkami openGym může mluvit.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Garmin Connect se nepodařilo zastihnout. Zkus to za chvíli znovu.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Vyber svůj Garmin v Garmin Connect a tréninky se objeví na zápěstí.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect zatím nezná žádné hodinky. Nejdřív v něm spáruj ty svoje.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym je na tvém Garminu. Série zapsané na zápěstí přijdou sem.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym je na tvém Garminu. Všechno dožene, jakmile budou hodinky v dosahu.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Tvůj Garmin je tady, ale openGym na něm ještě není. Stáhni ho a jednou ho na hodinkách otevři.",
  "Not in reach": "Mimo dosah",
  "openGym isn’t on it yet": "openGym na něm ještě není",
  "Your Garmins": "Tvoje Garminy",
  "Choose watches": "Vybrat hodinky",
  "Look again": "Hledat znovu",
  "Get openGym for Garmin": "Získat openGym pro Garmin",
  "Start a workout on the phone and your Garmin asks to open openGym.": "Začni trénink na telefonu a Garmin se zeptá, jestli má otevřít openGym.",
