  "Every week you showed up counted.": "Každý týden, kdy jsi přišel, se počítal.",
  "Everything aches": "Všechno bolí",
  "Exercise of the month": "Cvik měsíce",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Pro kartu Denní forma ve Statistikách a tvůj check-in. Čte se jen na tomto telefonu a nikam se neposílá.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Čtyři ťuknutí o spánku, energii, svalovici a stresu. V horší den ti openGym nabídne lehčí trénink a po pár týdnech uvidíš, co mají tvoje dobré dny společného.",
  "Frazzled": "Na nervy",
  "From Apple Health, read-only, on this phone only.": "Z Apple Health, jen pro čtení, jen na tomto telefonu.",
  "From Health Connect, read-only, on this phone only.": "Z Health Connect, jen pro čtení, jen na tomto telefonu.",
