  "Lighter day: one set fewer per exercise. Progression sits this one out.": "Lehčí den: o jednu sérii méně na cvik. Progrese tentokrát stojí.",
  "More than last month. Momentum looks good on you.": "Víc než minulý měsíc. Rozjezd ti sluší.",
  "New moves, new muscles asking questions. Curiosity pays.": "Nové pohyby, nové svaly se ptají. Zvědavost se vyplácí.",
  "Not a single week off. Your calendar is impressed.": "Ani jeden týden volna. Tvůj kalendář je ohromen.",
