  "Your month in openGym": "Tvůj měsíc v openGym",
  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym požádá Apple Health o tvůj spánek, klidovou tepovou frekvenci, variabilitu srdečního tepu a kroky. Povol, co chceš. Zůstanou na tomto telefonu, ve vlastním souboru openGym, a nikdy nejdou na server.",
  "openGym asks Health Connect for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym požádá Health Connect o tvůj spánek, klidovou tepovou frekvenci, variabilitu srdečního tepu a kroky. Povol, co chceš. Zůstanou na tomto telefonu, ve vlastním souboru openGym, a nikdy nejdou na server.",
