  "Sick or travelling? Mark a day of that week with a day note and the week is excused, no freeze spent (a few times a year).": "Nemocný nebo na cestách? Označ jeden den toho týdne poznámkou ke dni a týden je omluvený, bez spotřeby zmrazení (párkrát za rok).",
