  "Things the list has no word for. Your own exercises that need them show only here.": "Věci, pro které seznam nemá slovo. Tvoje cviky, které je potřebují, se ukážou jen tady.",
  "Three sets, from {0} up to {1} reps. Every set at {1} and the next rung is yours.": "Tři série, od {0} do {1} opak. Každá série na {1} a další příčka je tvoje.",
