  "You were injured, so this week is excused. The streak kept going and no freeze was spent.": "Byl jsi zraněný, takže tento týden je omluvený. Série běží dál a žádné zmrazení se nespotřebovalo.",
  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "Byl jsi nemocný, takže tento týden je omluvený. Série běží dál a žádné zmrazení se nespotřebovalo.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "Byl jsi na cestách, takže tento týden je omluvený. Série běží dál a žádné zmrazení se nespotřebovalo.",
