  "{0}% fewer sets, same weights. Recharge.": "O {0} % méně sérií, stejné váhy. Dobij baterky.",
  "{1} are still recovering, so they sit this one out.": "{1} ještě regenerují, takže tentokrát odpočívají.",
  "{1} is still recovering, so it sits this one out.": "{1} ještě regeneruje, takže tentokrát odpočívá.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "A tak to zůstane: openGym Offline nemá oprávnění k internetu, takže Android zablokuje cokoli, o co by se pokusil.",
  "Any of the sounds on your phone.": "Jakýkoli zvuk z telefonu.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Občas si udělej zálohu v Nastavení, Data a záloha. Soubor v telefonu je jediná kopie, která existuje.",
  "Closing the app resets the count; the log never leaves the phone.": "Zavření aplikace vynuluje počítadlo; záznam nikdy neopustí telefon.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Počítáno od {0}, kdy se aplikace spustila. Zavření ho vynuluje; záznam nikdy neopustí telefon.",
  "Each reminder can sound different, so you know which one it is before you look.": "Každá připomínka může znít jinak, takže víš, která to je, ještě než se podíváš.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Vše, na co se tato aplikace ptala internetu, nejnovější nahoře. Jen adresa, nikdy obsah.",
  "For reading mid-set without your glasses.": "Na čtení uprostřed série bez brýlí.",
  "Larger": "Ještě větší",
  "Last at {0}": "Naposledy v {0}",
  "Latest": "Nejnovější",
  "Less: no sliding, bouncing or snow. Things just appear.": "Méně: nic neklouže, neposkakuje ani nesněží. Věci se prostě objeví.",
  "Like the phone": "Jako telefon",
  "Mostly your own server, {0}, when there was something to sync.": "Hlavně tvůj vlastní server, {0}, když bylo co synchronizovat.",
  "Motion": "Pohyb",
  "Network log": "Záznam sítě",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "V openGym Offline není hledání na mapě. Postav se do posilovny, klepni na Aktuální poloha, hotovo.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Ani jeden bajt neopustil tento telefon. Tvůj trénink je jen tvoje věc.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Zatím nic. Tvůj server o tomto telefonu uslyší, když bude co synchronizovat.",
  "Phone default": "Výchozí v telefonu",
  "Phone sound": "Zvuk telefonu",
  "Pick a phone sound…": "Vybrat zvuk z telefonu…",
  "Showing the last {0}. The count above has them all.": "Posledních {0}. Počítadlo nahoře má všechny.",
  "Shows up, keeps quiet.": "Ukáže se, mlčí.",
  "Tap one to hear it. It rings even with the app closed.": "Klepni pro poslech. Zazvoní i při zavřené aplikaci.",
  "Text size": "Velikost textu",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "Tohle je openGym Offline: Android ho ani nepustí na internet. Chceš synchronizaci? Běžná aplikace openGym to umí, hned vedle.",
  "Weigh-ins, measurements and progress photos.": "Vážení, míry a fotky pokroku.",
  "Whatever your phone uses for notifications.": "Co telefon používá pro oznámení.",
  "When you walk into your gym.": "Když vejdeš do své posilovny.",
  "Who": "Kdo",
  "Who this app talked to since you opened it.": "S kým tato aplikace mluvila, od kdy jsi ji otevřel.",
  "Workout days and the nudge when one slips by.": "Tréninkové dny a šťouchnutí, když nějaký uteče.",
  "Workout reminders": "Připomínky tréninku",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offline nemá oprávnění k internetu. Tvůj trénink zůstává v tomto telefonu, tečka.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline nikdy nehledá aktualizace, nemůže. Nové verze najdeš tam, kde jsi vzal tuto.",
  "openGym Offline, no internet permission": "openGym Offline, bez oprávnění k internetu",
