  "Still training?": "Ještě trénuješ?",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "Už {0} min žádná série. Jestli máš hotovo, uzavřu ho za {1} min, s koncem na poslední sérii.",
  "Looks like you left the gym": "Vypadá to, že jsi odešel z posilovny",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "Ukončit trénink teď? Jinak skončí sám za {0} min.",
  "Keep going": "Pokračovat",
  "Finish now": "Ukončit teď",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "Ukončit trénink teď? Jinak skončí sám v {0}.",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Chvíli nic zapsáno. Jestli máš hotovo, skončí sám v {0}, uložený na poslední sérii.",
  "Forgotten workouts": "Zapomenuté tréninky",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Když nikdo neodpoví, skončí sám a nikdy nic nezahodí. Konec je tvoje poslední série plus její pauza, takže čas zůstane poctivý. V historii ho můžeš den znovu otevřít. Hodinky se ptají taky.",
